scenario.send:

INVITE urn:service:sos SIP/2.0
Via: SIP/2.0/${transport} ${local_ip}:${local_port};branch=${branch}
From: "NG911 Test" <sip:+12025551212@${local_ip}:${local_port}>;tag=${from_tag}
To: urn:service:sos
Call-ID: ${call_id}
CSeq: 1 INVITE
Contact: sip:+12025551212@${local_ip}:${local_port}
Max-Forwards: 70
Content-Type: application/sdp
Content-Length: 0

v=0
o=user1 53655765 2353687637 IN IP4 ${local_ip}
s=-
t=0 0
c=IN IP4 ${rtp_local_ip}
m=audio ${rtp_local_port} RTP/SAVP 0
a=rtpmap:0 PCMU/8000
a=crypto:1 AES_CM_128_HMAC_SHA1_80 inline:W/sWsVzpzxx69CLNZMObVPOLm/Ma1PicfhB59Plc
a=sendrecv


ACK urn:service:sos SIP/2.0
Via: SIP/2.0/${transport} ${local_ip}:${local_port};branch=${branch}
From: "NG911 Test" <sip:+12025551212@${local_ip}:${local_port}>;tag=${from_tag}
To: urn:service:sos${peer_tag_param}
Call-ID: ${call_id}
CSeq: 1 ACK
Contact: sip:+12025551212@${local_ip}:${local_port}
Content-Length: 0


BYE urn:service:sos SIP/2.0
Via: SIP/2.0/${transport} ${local_ip}:${local_port};branch=${branch}
From: "NG911 Test" <sip:+12025551212@${local_ip}:${local_port}>;tag=${from_tag}
To: urn:service:sos${peer_tag_param}
Call-ID: ${call_id}
CSeq: 2 BYE
Max-Forwards: 70
Contact: sip:+12025551212@${local_ip}:${local_port}
Content-Length: 0
